                    .pi_laurent_polynomial_retained::<RETAIN>(
                        budget - 1,
                        remaining_work,
                        memo,
                        reused,
                    )?
                    .scaled(Rational::new(-1)),
            ),
            Approximation::Offset(child, shift) => Some(
                child
                    .pi_laurent_polynomial_retained::<RETAIN>(
                        budget - 1,
                        remaining_work,
                        memo,
                        reused,
                    )?
                    .scaled(Self::power_of_two_rational(*shift)),
            ),
            Approximation::Inverse(child) => child
                .pi_laurent_polynomial_retained::<RETAIN>(
                    budget - 1,
                    remaining_work,
                    memo,
                    reused,
                )?
                .inverse_monomial(),
            Approximation::Square(child) => {
                let child = child.pi_laurent_polynomial_retained::<RETAIN>(
                    budget - 1,
                    remaining_work,
                    memo,
                    reused,
                )?;
                child.clone().multiply(child)
            }
            Approximation::Sqrt(child) => {
                let child = child.pi_laurent_polynomial_retained::<RETAIN>(
                    budget - 1,
                    remaining_work,
                    memo,
                    reused,
                )?;
