                let mut sum = PiLaurentPolynomial::monomial(
                    0,
                    RadicalCoefficient::rational(Rational::zero()),
                );
                for (coefficient, value) in combination
                    .coefficients
                    .iter()
                    .zip(combination.values.iter())
                {
                    sum = sum.add(
                        coefficient
                            .pi_laurent_polynomial_retained::<RETAIN>(
                                budget - 1,
                                remaining_work,
                                memo,
                                reused,
                            )?
                            .scaled(value.clone()),
                    )?;
                }
                Some(sum)
            }
            _ => None,
        })();
        expanded.or_else(|| {
            Some(PiLaurentPolynomial::monomial(
                0,
                RadicalCoefficient::atom(self.clone()),
            ))
        })
    };
    if shared {
        memo.get_or_insert_with(|| Vec::with_capacity(8))
            .push((key, result.clone()));
        if RETAIN
            && matches!(
                self.internal.approximation,
                Approximation::Add(_, _)
                    | Approximation::Multiply(_, _)
                    | Approximation::Negate(_)
                    | Approximation::Offset(_, _)
                    | Approximation::Inverse(_)
                    | Approximation::Square(_)
                    | Approximation::Sqrt(_)
                    | Approximation::LinearCombination3(_)
            )
            && let Some(polynomial) = &result
        {
            self.internal.cache.store_pi_laurent_polynomial(polynomial);
        }
    }
    result
